using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    [ColumnName("Probability")]
    public float Probability { get; set; }
}

using Microsoft.ML;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ChurnModelService
{
    private readonly PredictionEngine<CustomerData, ChurnPrediction> _predictionEngine;

    public ChurnModelService()
    {
        var mlContext = new MLContext();

        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
        var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

        var pipeline = mlContext.Transforms.Conversion.MapValue(
                "Label",
                new Dictionary<string, bool> { { "Yes", true }, { "No", false } },
                inputColumnName: "Churned")
            .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
            .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "PurchaseHistory", "RegionEncoded"))
            .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

        var model = pipeline.Fit(data);
        _predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);
    }

    public ChurnPrediction Predict(CustomerData input) => _predictionEngine.Predict(input);
}

