using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ChurnModelService>();
var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (PredictRequest request, ChurnModelService service) =>
{
    var customerData = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory
    };

    var prediction = service.Predict(customerData);

    return Results.Json(new { willChurn = prediction.PredictedLabel, probability = prediction.Probability });
});

app.Run();

record PredictRequest(float Age, float Income, string Region, float PurchaseHistory);

